\begin{nonclaim}[Closure-only scope]\label{nonclaim:main:closure-only-scope}
The theory does not claim that raw substrates, provisional packages, public shadows, or undeclared probe spaces contain no needles.  A no-needle theorem is asserted only for formed closures/layers with declared native probe families, null-mode legality, accepted predictive transport, adequacy or scoped nonclaim for dissolving probes, completed critical-pair ledgers, and all-six records.
\end{nonclaim}

\begin{nonclaim}[Applications]\label{nonclaim:main:applications}
The RH and Navier--Stokes sections are obligation maps.  They identify what a proof must supply.  They are not proofs of RH or Navier regularity.
\end{nonclaim}

\begin{nonclaim}[Duality-confinement scope]\label{nonclaim:main:duality-confinement-scope}
The duality-confinement theorem in Section~\ref{sec:duality-confinement} does not claim that every involutive system confines objects to its fixed locus.  It does not claim that invariant trace balance controls anti-invariant displacement.  It does not claim that moving finite windows with no tail record prove exact confinement.  It states the exact membrane records under which a fixed-locus confinement theorem follows.
\end{nonclaim}

\begin{remark}[Interpretation]\label{rmk:main:blind-spot-interpretation}
\(\XiRes_C(D\mid L)\) is the blind-spot currency: what the layer-dissolving probes see that the native probes do not.
\end{remark}

\begin{theorem}[Quantitative confinement]\label{thm:main:quantitative-confinement}
Assume quantitative separation.  Then
\[
\mu\{x:\dist(x,\Fix(J))\ge\varepsilon\}
\le
\frac{\tr\mathsf A_X}{m(\varepsilon)^2}.
\]
\end{theorem}

\begin{theorem}[Adequacy-aware transfer]\label{thm:main:adequacy-aware-transfer}
A lawful transfer of a layer-dissolving membrane must transport energy, native probes, dissolving probes, and adequacy residuals.  Exact bridges transfer the native and dissolving budgets by congruence.  Defective bridges produce explicit residual currencies; these must be paid in the target budget.
\end{theorem}

\begin{obligation}[Character-source coercivity]\label{obl:main:character-source-coercivity}
The anti-invariant character/source records must form a lower frame over the full anti-invariant response sector.  Invariant or trace-only control is insufficient.
\end{obligation}

\begin{remark}[Null-mode warning]\label{rmk:xi:null-mode-warning}
If a probe sees a legal zero-energy direction, the variational capacity is infinite even if a pseudoinverse expression appears finite.  Null-mode legality is therefore not a technicality; it is part of the adequacy record.
\end{remark}

\begin{definition}[Adequacy residual]\label{def:xi:adequacy-residual}
The adequacy residual of $D$ relative to $L$ is
\[
\boxed{\Xi_C(D\mid L)=K_{DD}-K_{DL}K_{LL}^\dagger K_{LD}.}
\]
\end{definition}

\begin{theorem}[Projection identity]\label{thm:xi:projection-identity}
\[
\boxed{\Xi_C(D\mid L)=T_D(I-P_L)T_D^*\succeq 0.}
\]
\end{theorem}

\begin{remark}\label{rmk:xi:projection-interpretation}
The theorem says that $\Xi_C(D\mid L)$ is the dissolving readout after removing the part explained by native probes in the energy-dual geometry.
\end{remark}

\begin{theorem}[Optimal residual identity]\label{thm:xi:optimal-residual-identity}
For every linear map $A:Y\to Z$,
\[
\boxed{(D_0-AL_0)C_0^{-1}(D_0-AL_0)^*
=\Xi_C(D\mid L)+(A-A_*)K_{LL}(A-A_*)^*.}
\]
Consequently, $\Xi_C(D\mid L)$ is the Loewner-minimal residual currency among all attempts to factor $D$ through $L$.
\end{theorem}

\begin{theorem}[Exact adequacy]\label{thm:xi:exact-adequacy}
The following are equivalent:
\begin{enumerate}[label=(\roman*)]
\item $\Xi_C(D\mid L)=0$;
\item $D_0=A_*L_0$;
\item there exists $A$ such that $D_0=AL_0$;
\item $\ker L_0\subseteq \ker D_0$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Adequacy promotion]\label{thm:xi:adequacy-promotion}
\[
\boxed{K_{DD}\preceq A_*\Theta_YA_*^*+\Xi_Z.}
\]
In particular, if $\Xi_C(D\mid L)=0$, native anti-localization transfers exactly to the dissolving family through $A_*$.
\end{theorem}

\begin{theorem}[Chain rule for adequacy residuals]\label{thm:xi:chain-rule}
\[
\boxed{\Xi_C(D\mid L^+)=\Xi_C(D\mid L)-K_{DM\mid L}K_{MM\mid L}^\dagger K_{MD\mid L}.}
\]
In particular,
\[
\Xi_C(D\mid L^+)\preceq \Xi_C(D\mid L).
\]
\end{theorem}

\begin{corollary}[Same-family saturation]\label{cor:xi:same-family-saturation}
If $M=BL$ for some $B$, then
\[
\Xi_C(D\mid[L;M])=\Xi_C(D\mid L).
\]
\end{corollary}

\begin{theorem}[Dissolving post-processing]\label{thm:xi:dissolving-post-processing}
For a response map $F:Z\to Z'$,
\[
\boxed{\Xi_C(FD\mid L)=F\Xi_C(D\mid L)F^*.}
\]
\end{theorem}

\begin{theorem}[Native coarsening]\label{thm:xi:native-coarsening}
For a native response map $A:Y\to Y'$,
\[
\boxed{\Xi_C(D\mid AL)\succeq \Xi_C(D\mid L).}
\]
If $A$ is a faithful reparameterization on $\Ran L_0$, equality holds.
\end{theorem}

\begin{theorem}[Blind-spot witness]\label{thm:xi:blind-spot-witness}
\[
\Xi_C(D\mid L)\npreceq \Omega
\]
if and only if there exists $z\in Z$ such that
\[
\boxed{z^*(\Xi_C(D\mid L)-\Omega)z>0.}
\]
The maximum additive violation is $\lambda_{\max}(\Delta_\Xi)$.
\end{theorem}

\begin{definition}[Bradshaw--Grujic frequency-window import]\label{def:ns:bg-import}
The Bradshaw--Grujic frequency-window regularity criterion is imported as the proof-carrying record asserting that a strong solution $u$ has $\Tmax=\infty$ whenever the frequency-window observable
\[
\DBG_{J,t}\quad\text{is uniformly bounded on a doubling sequence of BG stages with $\lambda_{j+1}=2\lambda_j$.}
\]
Realized in Lean as a structure carrying the window-bound conclusion under named hypotheses on the BG package $\Gamma_j$.
\end{definition}

\begin{definition}[Half-log analyticity import]\label{def:ns:wang-halflog-import}
The Foias--Temam / Herbst--Skibsted / Wang-style half-log analyticity result is imported as the proof-carrying record asserting that for restart data in $H^{\gamma_0}\cap\dot B^{-\eps}_{\infty,\infty}$ with $\gamma_0>3/2-\eps$, the analyticity radius admits the half-log lower bound
\[
\rho(t)\gtrsim\frac{\log\lambdaJ(t)}{\lambdaJ(t)}
\]
on BG-compatible stages of the smooth-data subcarrier.  Realized in Lean as a structure carrying the radius bound under named hypotheses; the bound itself is paper-grounded, not derived.
\end{definition}

\begin{definition}[Littlewood--Paley and Bony--Chemin--Danchin calculus import]\label{def:ns:lp-bcd-import}
The Littlewood--Paley / Bony--Chemin--Danchin paradifferential calculus is imported as the proof-carrying record carrying the operator-norm bounds, commutator estimates, and shell-orthogonality identities on which the LP transport map $\LPtr$ and the half-log staged residuals depend.  Realized in Lean as a structure whose fields are the (paper-grounded) commutator and shell-orthogonality records consumed downstream.
\end{definition}

\begin{definition}[Sobolev/Besov embedding chain import]\label{def:ns:sobolev-besov-embedding-import}
The standard Sobolev/Besov embedding chain
\[
H^{\gamma_0}\hookrightarrow \dot B^{-\eps}_{\infty,\infty}
\qquad (\gamma_0>3/2,\ \eps>0\text{ admissible})
\]
is imported as the proof-carrying record that lifts smooth $H^{\gamma_0}$ restart data into the joint hypothesis space $H^{\gamma_0}\cap\dot B^{-\eps}_{\infty,\infty}$ of \Cref{def:ns:wang-halflog-import}.  Realized in Lean as an embedding structure whose constructor consumes the smooth-data hypothesis and exposes the joint Besov-compatible regularity.
\end{definition}

\begin{theorem}[Source-admission recurrence]\label{thm:ns:source-admission-recurrence}
Under records $R_3$ (null-mode legality) and $R_4$ (source-admission acceptance), for every BG stage $J$ and time $t$ and every time-step $h>0$,
\[
\boxed{\Xi_{C_{J,t+h}}(\DBG_{J,t+h}\mid \Lphys_{J,t+h})\preceqq C_{\mathrm{old}}\,\mathcal T_h\,\Xi_{C_{J,t}}(\DBG_{J,t}\mid \Lphys_{J,t})\,\mathcal T_h^*+\Omtr+\Ompr+\Omvisc+\Omtail+\Omstr,}
\]
where $\mathcal T_h$ is the accepted stage-to-stage transport map, declared to descend to the legal energy quotient via $\mathcal T_h(\Ker C_{J,t})\subseteq \Ker C_{J,t+h}$ so that the recurrence is typed on $E_{J,t}/\Ker C_{J,t}$, and $C_{\mathrm{old}}\ge 0$ is the carry-forward constant.  On the smooth-data Sobolev carrier $C_{J,t}$ is positive-definite on $E_{J,t}$, so $\Ker C_{J,t}=\{0\}$ and the descent is automatic.
\end{theorem}

\begin{theorem}[No-go NG2: scalar energy / enstrophy category error]\label{thm:ns:no-go-scalar-energy}
Quadratic energy or enstrophy scalars do not constitute a linear native probe family.  In particular, for a positive scalar functional $E_{J,t}\colon E_{J,t}\to\R_{\ge 0}$ that is quadratic in the input, the adequacy residual $\Xi_C(\DBG\mid E_{J,t})$ is not well-formed as an object of the Schur-complement calculus until a lawful linear native family $L$ has been declared and audited.
\end{theorem}

\begin{theorem}[No-go NG3: packing / amplitude]\label{thm:ns:no-go-packing-amplitude}
For a bad set of size $\sim r^{3-d}$ and amplitude $\sim r^{-\alpha}$, the contribution to $\|\DBG u\|$ scales as $r^{(3-d)/2-\alpha}$.  Amplitude suppression by packing alone requires $\alpha<(3-d)/2$; otherwise small-set sparseness does not control $\DBG$-amplitude, and the no-go forces a sector-matched amplitude bridge or paid tail-smallness record.
\end{theorem}

\begin{theorem}[No-go NG4: sparse-shadow]\label{thm:ns:no-go-sparse-shadow}
Imported sparse or intense sets do not pay $\Omega_{\mathrm{bb}}$ (bad-cylinder / bad-geometry overlap) unless either the sparse field is sector-contained in the bad-bad / mismatch sector or a paid mismatch record $\Omega_{\mathrm{mm}}\succeq 0$ is supplied.
\end{theorem}

\begin{theorem}[No-go NG5: marker-only]\label{thm:ns:no-go-marker-only}
Triad markers, bad-overlap masks, and similar marker-only fields identify where and what class a defect lives in, but do not dominate the $\DBG$-amplitude without a quantitative bridge.  Promotion from marker payload to $\Omamp$ requires an amplitude bridge supplied either by a new native probe family (\Cref{thm:ns:source-admission-recurrence}) or by a record-grade $M^{\mathrm{bb}}$ bound.
\end{theorem}

\begin{theorem}[No-go NG6: metric-shadow]\label{thm:ns:no-go-metric-shadow}
Weighted or Gevrey-flavored metrics that shrink the apparent residual do not control the fixed $\DBG$ readout unless the normalized metric still dominates the BG/BKM amplitude.  Concretely, geometry inputs from Caffarelli--Kohn--Nirenberg parabolic regularity or Constantin--Fefferman vorticity-direction geometry act as metric shadows, and a sector-matched amplitude bridge plus an explicit dominance constant and time gate must be supplied as a separate record.
\end{theorem}

\begin{theorem}[No-go NG7: moving-window / derivative-stack support-only]\label{thm:ns:no-go-moving-window}
Finite Littlewood--Paley windows or derivative-stack windows that are merely supported on moving sets do not promote to a completed carrier closure.  Promotion requires either a finite-termination record, a fixed-ledger squeeze, or an exhaustive-ledger squeeze; moving-window data alone is theorem-grade insufficient.
\end{theorem}

\begin{theorem}[No-go NG9: available analyticity ceiling for the direct route]\label{thm:ns:no-go-published-analyticity}
The available half-log analyticity lane of \Cref{def:ns:wang-halflog-import} is short by $\sqrt{\log\lambdaJ}$ for the direct radius-window gate of \Cref{thm:ns:gevrey-dominance}.  Closing the direct route therefore requires either the LP transport rescue of \Cref{thm:ns:lp-transport-rescue}, the proof of a strictly stronger full-log analyticity radius, or an alternative new-radius theorem outside the present scope.
\end{theorem}

\begin{theorem}[No-go NG10: raw nonlinearity illegal as Schur probe]\label{thm:ns:no-go-raw-nonlinearity}
Raw nonlinear observables -- flux, pressure interaction, vortex stretching, triads -- cannot enter the native family $\Lphys$ as Schur-complement probes.  Lawful entry requires either tangent-linearization, interaction-lifting to a higher-order linearization, or recording the nonlinear contribution as a source-admission entry in $\Omsrc$ (\Cref{def:ns:source-admission-ledger}).
\end{theorem}

\begin{definition}[LP transport stage operator]\label{def:ns:lp-transport}
The Littlewood--Paley transport stage operator $\LPtr$ is the map
\[
\LPtr\colon L^2(P_j)\to H^{-s}
\]
with $s\ge q-\eps$ and operator-norm bound
\[
\|\LPtr\|^2\simeq 2^{-2sj}
\]
on a BG-compatible doubling sequence $\lambda_{j+1}=2\lambda_j$.  Realized in Lean as a record carrying the response space, the exponent $s$, and the norm-bound constant.
\end{definition}

\begin{theorem}[Framework-deliverable NS regularity]\label{thm:ns:framework-deliverable-regularity}
Under the Six Birds closure record bundle $\mathsf R=(R_1,\ldots,R_9)$ of \Cref{def:ns:closure-r1-r9} and the typed-context discipline of the formed-layer membrane and adequacy-residual frameworks, for every divergence-free initial datum $u_0\in H^{\gamma_0}$ with $\gamma_0>5/2$ on the accepted smooth-data channel,
\[
\boxed{\Tmax(u_0)=\infty.}
\]
\end{theorem}

\begin{definition}[NS smooth-data carrier as an AOR-instance object]\label{def:ns:aor-instance-object}
The Navier--Stokes smooth-data carrier with initial datum $u_0\in H^{\gamma_0}$, $\gamma_0>5/2$, is the AOR-instance object $\mathsf C_{\mathrm{NS}}$ whose carrier family is the Bradshaw--Grujic frequency-refinement chain $H_{J,t}=E_{J,t}/\Ker C_{J,t}$ indexed by BG stages $J\in\mathbb N$ and time $t<\Tmax(u_0)$, with refinement morphisms $J\mapsto J+1$ of combined kind A3+A6.  Its AOR registries are populated by the records of \S\ref{sec:ns-carrier}--\S\ref{sec:ns-gevrey-lp}: physical-native probes $\Lphys$ and target readout $\DBG$ as observation records; the BG-windowed package $\Gamma_j$, audited transport $\mathcal T_h$, and LP-transport $S_j$ as route records; the source-admission ledger $\Omsrc$ as source records; the BG window $P_{J(t)}$ as the bounded interface; null-mode legality, positivity, and the Loewner recurrence as constraints; the half-log radius bound as a scale record; and the present paper's nonclaim list as the nonclaim register.  The scope $\mathfrak S_{\mathrm{NS}}$ restricts to smooth divergence-free Sobolev data.
\end{definition}

\begin{theorem}[Mechanical closure records as AOR-membership components]\label{thm:ns:aor-mechanical-r-records}
Six of the nine standing closure records of $\mathsf C_{\mathrm{NS}}$ admit by-construction or approved-other discharges within scope $\mathfrak S_{\mathrm{NS}}$: $R_1$ (adequacy orientation), $R_2$ (exact BG-windowed package), $R_3$ (null-mode legality), $R_5$ (BG frequency-doubling staging), and $R_9$ (nonclaim boundary) discharge \texttt{by\_construction}; $R_8$ (paper-grounded PDE imports: BKM, BG, Kato, half-log analyticity, LP/BCD, Sobolev/Besov embedding) discharges \texttt{approved\_other} as an external-record citation chain.  These six records contribute the mechanical components of the AOR-membership witness; the substantive components $R_4,R_6,R_7$ follow.
\end{theorem}

\begin{theorem}[Substantive discharge of $R_4$ as a membership component]\label{thm:ns:aor-r4-discharge}
The source-admission recurrence record $R_4$ of $\mathsf C_{\mathrm{NS}}$ has primary type $\Delta_{\mathrm{source}}$ and forced secondary types $\Delta_{\mathrm{transport}},\Delta_{\mathrm{scale}},\Delta_{\mathrm{target}},\Delta_{\mathrm{role}}$.  Its discharge status decomposes as $(\Delta_{\mathrm{source}},\texttt{budgeted}\text{ per stage})+(\Delta_{\mathrm{transport}},\texttt{zero})+(\Delta_{\mathrm{scale}},\texttt{cross-cascade to }R_6,R_7)$, with the Loewner recurrence as the budgeted witness and the quotient-transport record \Cref{thm:ns:aor-quotient-transport-record} as the zero-transport witness.  $R_4$ is per-stage budgeted; its asymptotic propagation is not standalone, and is paid by the $R_6/R_7$ cross-cascade.
\end{theorem}

\begin{theorem}[Substantive discharge of $R_6$ as a membership component]\label{thm:ns:aor-r6-discharge}
The dissolving-side LP-transport record $R_6$ of $\mathsf C_{\mathrm{NS}}$ has primary type $\Delta_{\mathrm{transport}}$ and forced secondary types $\Delta_{\mathrm{scale}},\Delta_{\mathrm{limit}},\Delta_{\mathrm{target}},\Delta_{\mathrm{role}},\Delta_{\mathrm{presentation}}$.  Its discharge status decomposes as $(\Delta_{\mathrm{transport}},\texttt{zero})+(\Delta_{\mathrm{scale}},\texttt{contractive on a cofinal tail})+(\Delta_{\mathrm{limit}},\texttt{summable})$ for every $s>p=q-\eps$, with the LP-transport rescue \Cref{thm:ns:lp-transport-rescue} as the witness for both the contractive-tail and summable statuses; the stage ratio satisfies $\widetilde B_{j+1}(s)/\widetilde B_j(s)\to 2^{2(p-s)}<1$.
\end{theorem}

\begin{theorem}[Substantive discharge of $R_7$ as a membership component]\label{thm:ns:aor-r7-discharge}
The half-log analyticity / smooth-data transfer record $R_7$ of $\mathsf C_{\mathrm{NS}}$ has primary type $\Delta_{\mathrm{scale}}$ and forced secondary types $\Delta_{\mathrm{limit}},\Delta_{\mathrm{horizon}},\Delta_{\mathrm{source}},\Delta_{\mathrm{target}},\Delta_{\mathrm{presentation}}$.  Its discharge status decomposes as $(\Delta_{\mathrm{scale}},\texttt{zero})+(\Delta_{\mathrm{limit}},\texttt{asymptotic\_budgeted, basic gate})+(\Delta_{\mathrm{horizon}},\texttt{out\_of\_scope/nonclaim})$, with \Cref{thm:ns:smooth-data-half-log-transfer} as the zero-scale witness, the half-log radius bound $\rho(t)\gtrsim\log\lambdaJ(t)/\lambdaJ(t)$ as the basic-gate witness, and the smooth-data Sobolev restriction as the horizon nonclaim.  $R_7$ is not contractive on its own; contraction is supplied by $R_6$.
\end{theorem}

\begin{theorem}[Quotient-transport record $R_{4q}$]\label{thm:ns:aor-quotient-transport-record}
The audited transport map $\mathcal T_h$ of $\mathsf C_{\mathrm{NS}}$ descends to the legal energy quotient:
\[
  \mathcal T_h(\Ker C_{J,t}) \;\subseteq\; \Ker C_{J,t+h}
\]
for every admissible $(J,t,h)$, so the induced map $\bar{\mathcal T}_h:E_{J,t}/\Ker C_{J,t}\to E_{J,t+h}/\Ker C_{J,t+h}$ is well-defined and the Loewner recurrence is typed on the legal quotient.  On the smooth-data Sobolev carrier the audit form $C_{J,t}$ is positive-definite on $E_{J,t}$, so $\Ker C_{J,t}=\{0\}$ and the descent is automatic.
\end{theorem}

\begin{theorem}[NS smooth-data carrier in $\mathbf{AOR}^{\mathrm{ref}}$]\label{thm:ns:in-refstableaor}
Under the discharges of \Cref{thm:ns:aor-mechanical-r-records}, \Cref{thm:ns:aor-r4-discharge}, \Cref{thm:ns:aor-r6-discharge}, and \Cref{thm:ns:aor-r7-discharge}, together with the quotient-transport record of \Cref{thm:ns:aor-quotient-transport-record}, the Navier--Stokes smooth-data carrier $\mathsf C_{\mathrm{NS}}$ belongs to $\mathbf{AOR}^{\mathrm{ref}}_{\mathfrak S_{\mathrm{NS}}}$.  By the AOR meta-theory's discipline, audit-closure membership is the record-level reading of ``the carrier does not blow up in reality''; the framework-deliverable regularity statement \Cref{thm:ns:framework-deliverable-regularity} is the same content read in conditional form, with the closure stack presented as hypotheses rather than as the membership witness.
\end{theorem}

\begin{nonclaim}[Outside-framework reading]\label{nonclaim:ns:outside-framework}
Outside the Six Birds closure framework, \Cref{thm:ns:framework-deliverable-regularity} reads as the conditional implication
\[
  \bigl(\mathsf R\text{ holds on the smooth-data carrier}\bigr)
  \Longrightarrow
  \bigl(\Tmax(u_0)=\infty\bigr).
\]
This paper does not claim:
\begin{enumerate}
\item a standalone Clay-Millennium
solution~\citep{Fefferman2000NavierStokes} independent of the Six
Birds closure discipline;
\item generic critical-Besov data regularity outside the smooth-data
subcarrier \(H^{\gamma_0}\), \(\gamma_0>5/2\), in the sense of
critical-space well-posedness
results~\citep{KochTataru2001,Cannone1995,LemarieRieusset2023};
\item a criterion-native rewriting of \(\DBG\) in place of
physical-native adequacy, as ruled out by
\Cref{thm:ns:no-go-criterion-native};
\item that any single PDE input alone closes the problem, since the
argument uses the full \(R_1,\ldots,R_9\) bundle architecture;
\item engagement with Caffarelli--Kohn--Nirenberg partial
regularity~\citep{CaffarelliKohnNirenberg1982}, which concerns
Leray--Hopf weak solutions~\citep{Leray1934,Hopf1951} on a different
carrier class;
\item an untyped global comparison, since every comparison in the proof
is made inside the typed-context discipline;
\item a full-log analyticity radius theorem, since the paper uses only
the available half-log analyticity import together with the
LP-transport rescue.
\end{enumerate}
\end{nonclaim}

\begin{nonclaim}[AOR-instance reading restricted to smooth-data subcarrier]\label{nonclaim:ns:aor-instance-smooth-data-only}
The AOR-instance reading of \Cref{sec:ns-aor-instance}, including \Cref{thm:ns:in-refstableaor}, is restricted to the smooth-data Sobolev subcarrier $u_0\in H^{\gamma_0}$, $\gamma_0>5/2$.  No AOR-membership claim is made for generic critical-Besov data, weak solutions, distributional carriers, or any class outside the declared scope $\mathfrak S_{\mathrm{NS}}$.  The $\Delta_{\mathrm{horizon}}$ residual stratum is explicitly statused as \texttt{out\_of\_scope/nonclaim} in \Cref{thm:ns:aor-r7-discharge}.
\end{nonclaim}

\begin{nonclaim}[No independent Clay-Millennium claim via AOR instance]\label{nonclaim:ns:aor-instance-no-clay-claim}
\Cref{thm:ns:in-refstableaor} establishes membership of $\mathsf C_{\mathrm{NS}}$ in $\mathbf{AOR}^{\mathrm{ref}}$ under the discharges of $R_1$--$R_9$ and the carrier-attached discharge assignment.  Independently of those audit records and of the six declared PDE imports of $R_8$, the result is not a Clay-Millennium claim; the AOR-instance reading reframes the closure stack as the membership witness but does not assert global Navier--Stokes regularity outside the audit-record presentation.
\end{nonclaim}

\begin{definition}[Closure-completion operator]\label{def:aor:cl-sb-operator}
The \emph{closure-completion operator}
$\ClSB:\PreSB_{\mathfrak S}\to\AOR_{\mathfrak S}$ assigns to a PreSB
carrier $\mathsf C$ the carrier obtained as the least fixed point of
the monotone-saturation map
\[
  \mathsf C \;\longmapsto\;
  \mathsf C \cup \{\text{minimal AOR-extending operations on }\mathsf C\}
\]
on the complete lattice of AOR-extending operations over the scope
$\mathfrak S$, together with the reflection unit
$\eta_{\mathsf C}:\mathsf C\to\ClSB(\mathsf C)$ given by the inclusion
of the seed carrier into its saturation.
\end{definition}

\begin{definition}[Structural defect $\XiSB$]\label{def:aor:xi-sb}
The \emph{structural defect} $\XiSB(\mathsf C)$ of a PreSB carrier
$\mathsf C$ is the disjoint sum of its eight defect strata,
\begin{align*}
  \XiSB(\mathsf C)
  \;=\;& \Sigobs(\mathsf C) \sqcup \Sigstage(\mathsf C) \sqcup \Sigconstr(\mathsf C) \sqcup \Sigrewrite(\mathsf C) \\
  & {} \sqcup \Sighol(\mathsf C) \sqcup \Sigres(\mathsf C) \sqcup \Signon(\mathsf C) \sqcup \Sigmeta(\mathsf C),
\end{align*}
with the strata defined in \Cref{def:aor:sigma-obs}--\Cref{def:aor:sigma-meta}.
The carrier is AOR exactly when every stratum is empty.
\end{definition}

\begin{definition}[$\Sighol$ stratum]\label{def:aor:sigma-holonomy}
The \emph{holonomy defect stratum} $\Sighol(\mathsf C)$ is the multiset
of route-dependent memory records whose carrier transport, source-ledger
attribution, or nonclaim flag is not declared.  The stratum is empty
iff every $\mathrm{Hol}$ entry has a typed carrier-route.
\end{definition}

\begin{definition}[Residual atom]\label{def:aor:residual-atom}
A residual record $a\in\Sigres$ is an \emph{atom} if it is minimal
under $\preceq_{\mathrm{res}}$ among non-empty records.  Equivalently,
$a$ has a unique primary type and no proper non-empty refinement.
\end{definition}

\begin{theorem}[Atom decomposition]\label{thm:aor:atom-decomposition}
Every residual record $r\in\Sigres$ admits a finite decomposition
$r=\bigsqcup_{i} a_i$ as a disjoint sum of atoms.  The decomposition is
unique up to permutation, and is computable from the carrier field
data.
\end{theorem}

\begin{definition}[Downstream operator]\label{def:aor:down-operator}
The \emph{downstream operator} $\mathrm{Down}$ acts on a residual
record $r$ with discharge witness $(a_i,s_i,\pi_i)$ by
\[
  \mathrm{Down}(r,\{(a_i,s_i,\pi_i)\})
  \;=\;
  \bigsqcup_i \mathrm{Cost}(\mathrm{type}(a_i),s_i)
\]
viewed as a new residual record of fresh atoms to be statused.
\end{definition}

\begin{theorem}[Bipartite cascade graph]\label{thm:aor:cascade-bipartite}
For every residual record $r$ and every choice of discharge witness,
the cascade graph $G(r)$ is bipartite: edges alternate between
atom-vertices and witness-vertices, and no edge connects two vertices
of the same kind.
\end{theorem}

\begin{definition}[Six refinement kinds]\label{def:aor:refinement-kinds-six}
A refinement morphism's per-field annotations belong to one of six
disjoint kinds:
\textbf{A1} scope expansion (enlarging $\mathfrak S$ within a fixed
scope chain);
\textbf{A2} record-field expansion (adding admissible records to one
of the registries);
\textbf{A3} stage / refinement-axis growth (extending $\mathrm{Stage}$
by a new stage);
\textbf{A4} constraint tightening (replacing a constraint by a
strictly stronger one);
\textbf{A5} morphism strengthening (replacing a morphism by a
refinement of itself);
\textbf{A6} carrier (probe / target) refinement (replacing $(H,q,Q)$
or a probe/target family by a finer version, with a declared
projection map).
\end{definition}

\begin{definition}[$\RefPreSB$ category]\label{def:aor:refpresb-category}
The category $\RefPreSB_{\mathfrak S}$ is the full category of PreSB
carriers of scope $\mathfrak S$ with refinement morphisms.  A
\emph{refinement chain} is a directed diagram in
$\RefPreSB_{\mathfrak S}$ indexed by a directed poset.
\end{definition}

\begin{definition}[Asymptotic statuses]\label{def:aor:asymptotic-statuses}
For a residual atom $a$ of a colimit object
$\mathsf C_\infty=\mathrm{colim}_j\mathsf C_j$, the
\emph{asymptotic statuses} extending AOR-8 are:
\texttt{asymptotic\_budgeted} (there exists a uniform finite budget
$B$ and a tail index $J_0$ with the per-stage cost bounded by $B$ for
all $j\ge J_0$);
\texttt{summable} (the per-stage costs are summable across the
directed chain);
\texttt{contractive} (the per-stage cost ratios tend to a constant
strictly less than $1$);
\texttt{eventual\_zero} (the per-stage cost is zero for all $j\ge J_0$
for some tail index $J_0$).
\end{definition}

\begin{theorem}[Hierarchy]\label{thm:aor:hierarchy}
The three classes form a strict containment chain,
\[
  \RefStableAOR_{\mathfrak S}
  \;\subsetneq\;
  \CascadeStableAOR_{\mathfrak S}
  \;\subsetneq\;
  \AOR_{\mathfrak S}.
\]
The first inclusion is witnessed by carriers whose cascade closes with
AOR-8 statuses but whose colimit residual cannot be paid by any
asymptotic status; the second by carriers in $\AOR_{\mathfrak S}$
admitting a residual atom that requires an unbounded cascade.
\end{theorem}
